<?php
use Illuminate\Support\Facades\Route; use App\Http\Controllers\InternalPaymentController; use App\Http\Controllers\WebhookController;
Route::prefix('internal/v1')->middleware('throttle:60,1')->group(function(){Route::post('payment-intents',[InternalPaymentController::class,'create'])->middleware('service:payments.write');Route::get('payment-intents/{id}',[InternalPaymentController::class,'show'])->middleware('service:payments.read');Route::post('payment-intents/{id}/cancel',[InternalPaymentController::class,'cancel'])->middleware('service:payments.write');Route::post('payment-intents/{id}/confirm-cash',[InternalPaymentController::class,'confirmCash'])->middleware('service:payments.write');Route::post('payment-intents/{id}/refunds',[InternalPaymentController::class,'refund'])->middleware('service:payments.write');Route::get('refunds/{id}',[InternalPaymentController::class,'refundShow'])->middleware('service:payments.read');Route::get('transactions/{id}',[InternalPaymentController::class,'transactions'])->middleware('service:payments.read');Route::get('reconciliations',[InternalPaymentController::class,'reconciliations'])->middleware('service:payments.read');});
Route::post('webhooks/v1/tilopay',[WebhookController::class,'tilopay'])->middleware('throttle:30,1');
